abstract class PregnancyEvent{const PregnancyEvent();}class PregnancyStarted extends PregnancyEvent{const PregnancyStarted();}class PregnancyRefreshed extends PregnancyEvent{const PregnancyRefreshed();}class PregnancyFilterBySpecialty extends PregnancyEvent{final String specialty;const PregnancyFilterBySpecialty(this.specialty);}class PregnancySearch extends PregnancyEvent{final String query;const PregnancySearch(this.query);}class PregnancyUpdateTracker extends PregnancyEvent{final Map<String,dynamic> data;const PregnancyUpdateTracker(this.data);}